using System;using System.IO;using System.Linq;using System.ComponentModel;using System.Globalization;using System.Reflection;using System.Drawing;using System.Windows.Forms;
namespace DoomSNESed {
    public static class CatalogSectorTests {
        static void Check(bool value,string message){Bin.Require(value,"Catalog/sectors: "+message);}
        static object Field(object o,string name){return o.GetType().GetField(name,BindingFlags.NonPublic|BindingFlags.Instance).GetValue(o);}
        static object Call(object o,string name,params object[] args){return o.GetType().GetMethod(name,BindingFlags.NonPublic|BindingFlags.Instance).Invoke(o,args);}
        public static void Run(string path,string output){string resources=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"editor-data"),folder=Path.Combine(output,"catalog-019");Directory.CreateDirectory(folder);var rom=new Rom(path,resources);Check(rom.WallTextures.SequenceEqual(Enumerable.Range(0,63).Select(i=>i*2)),"all 63 native table entries exposed");
            var referenced=rom.Project.Maps.SelectMany(m=>m.Faces.SelectMany(f=>f.Solid?new[]{f.Upper}:new[]{f.Upper,f.Lower})).Distinct().ToArray();int[] missing=rom.WallTextures.Except(referenced).ToArray();Console.WriteLine("Catalog: previously unreferenced native IDs: "+string.Join(", ",missing));Check(missing.Length>0,"fixture includes animation-only assets");
            string[] switches={"BRN2","BRNGN","EXIT","GARG","GRAY","GSTON","HOT","PIPE","SLAD","WOOD"};for(int i=0;i<10;i++){int off=(38+i)*2,on=(48+i)*2;Check(NativeWallCatalog.Name(off)=="SW1"+switches[i]&&NativeWallCatalog.Name(on)=="SW2"+switches[i],"off/on names match DoomFX order");foreach(int id in new[]{off,on})using(var p=new AssetPreview()){p.ShowWall(rom,id);Check(p.HasImage,"every switch state previews");}}
            foreach(string source in new[]{path,Path.Combine(Path.GetDirectoryName(path),"RL5934.sfc")}){if(!File.Exists(source))continue;var r=new Rom(source,resources);foreach(int id in r.WallTextures){var a=GraphicsAssets.Describe(r.Bytes,false,id);Check(GraphicsAssets.Decode(r.Bytes,a).Length==a.Width*a.Height,"complete catalog decodes for retail and source layouts");}}
            Context.Rom=rom;var converter=new WallTextureConverter();foreach(int id in rom.WallTextures){string label=(string)converter.ConvertTo(null,CultureInfo.InvariantCulture,id,typeof(string));Check((int)converter.ConvertFrom(null,CultureInfo.InvariantCulture,label)==id,"named property value round trip");}
            var wadConverter=new WadConverter(rom,resources);foreach(int id in Enumerable.Range(48,10).Select(i=>i*2))Check((int)Call(wadConverter,"Wall",NativeWallCatalog.Name(id))==id,"PWAD switch-on names map without substitutions");
            using(var picker=new AssetDialog(rom,true,false,96)){var list=(ListView)Field(picker,"list");Check(list.Items.Count==63&&list.Items.Cast<ListViewItem>().Count(i=>i.Text.Contains("switch on"))==10,"editor picker lists all switch-on thumbnails");}
            using(var form=new EditorForm(null)){Call(form,"LoadRom",path);Call(form,"SelectMode","Sectors");Call(form,"SelectItem",3);var grid=(PropertyGrid)Field(form,"properties");var descriptor=TypeDescriptor.GetProperties(grid.SelectedObject)["InternalSectorNumber"];Check(descriptor!=null&&descriptor.IsReadOnly&&(int)descriptor.GetValue(grid.SelectedObject)==3,"selected sector internal ID visible and read only");var canvas=(MapCanvas)Field(form,"canvas");canvas.Size=new Size(900,650);canvas.Fit();using(var image=new Bitmap(900,650)){canvas.DrawToBitmap(image,new Rectangle(0,0,900,650));image.Save(Path.Combine(folder,"sector-labels.png"));}}
            // Exercise newly exposed art as both a placed surface and a native
            // replacement, not just a catalog thumbnail.
            var build=new Rom(path,resources);var room=MapTemplates.Starter(build,0);foreach(var face in room.Faces)face.Upper=96;build.Project.Maps[0]=room;build.Project.CampaignSlots=new[]{0};var asset=GraphicsAssets.Describe(build.Bytes,false,96);byte[] pixels=GraphicsAssets.Decode(build.Bytes,asset);pixels[0]=(byte)(pixels[0]^1);build.Project.Graphics.Add(new GraphicReplacement{Id=96,Width=asset.Width,Height=asset.Height,Pixels=pixels});byte[] compiled=build.Compile();Check(GraphicsAssets.Decode(compiled,GraphicsAssets.Describe(compiled,false,96)).SequenceEqual(pixels),"previously hidden switch replacement survives build");string saved=Path.Combine(folder,"switch-on");File.WriteAllBytes(saved+".sfc",compiled);build.SavePatch(saved+".dse",compiled);build.SaveProject(saved+".sned");var reopened=new Rom(saved+".sfc",resources);Check(reopened.Project.Maps[0].Faces.All(f=>f.Upper==96),"previously hidden switch can be assigned to native map faces");
            File.WriteAllText(Path.Combine(output,"catalog-sector-019-results.txt"),"PASS all 63 textures and ten switch pairs, retail/source decoding, named texture values, full picker thumbnails, read-only internal sector index, sector-label render, hidden switch assignment/replacement and native ROM reimport.\r\n");
        }
    }
}
